const sheet=document.querySelector('.sheet'),scrim=document.querySelector('.scrim'),list=document.querySelector('.reader-viewport'),pending=document.querySelector('.pending');let timer;const dismiss=()=>{sheet.hidden=true;scrim.hidden=true};document.querySelector('#open').onclick=()=>{sheet.hidden=false;scrim.hidden=false};scrim.onclick=dismiss;const handle=document.querySelector('.handle');handle.onclick=dismiss;let y=0;handle.onpointerdown=e=>{y=e.clientY;handle.setPointerCapture(e.pointerId)};handle.onpointerup=e=>{if(e.clientY-y>60)dismiss()};document.onkeydown=e=>{if(e.key==='Escape')dismiss()};const rows=loading=>{list.classList.toggle('loading',loading);list.innerHTML=(loading?['','','']:['Саша','Маша','Соня','Никита','Олег']).map(name=>`<div class="person"><span class="avatar"></span><span>${name||'Имя участника'}</span></div>`).join('')};document.querySelector('#loading').onclick=()=>rows(true);document.querySelector('#loaded').onclick=()=>rows(false);document.querySelector('#send').onclick=()=>{clearTimeout(timer);pending.classList.remove('visible');timer=setTimeout(()=>pending.classList.add('visible'),2000)};document.querySelector('#ack').onclick=()=>{clearTimeout(timer);pending.classList.remove('visible')};document.querySelectorAll('.category').forEach(button=>button.onclick=()=>{document.querySelectorAll('.category').forEach(item=>item.setAttribute('aria-pressed',String(item===button)))});rows(true);
